$r = Invoke-RestMethod -Uri "http://localhost:5005/api/auth/login" -Method Post -Body '{"username":"admin","password":"admin"}' -ContentType "application/json"; $t = $r.token; $decl = Invoke-RestMethod -Uri "http://localhost:5005/api/declarations" -Method Post -Headers @{Authorization="Bearer $t"} -Body '{"societeId":1,"exercice":2026,"periode":1,"type":0}' -ContentType "application/json"; $id = $decl.id; $items = (Invoke-RestMethod -Uri "http://localhost:5005/api/declarations/$id/lignes?domaine=Decaissement&page=1&size=2000" -Method Get -Headers @{Authorization="Bearer $t"}).items; Write-Host "Total: $($items.Count)"; $items | Group-Object statutLigne; Write-Host ""; $items | Where-Object {$_.statutLigne -eq 0} | Select-Object -First 5 | Format-Table -Property motif, statutLigne, tauxTVA, montantTVA, montantTTC
